#!/usr/bin/env sh
# Senzu Theme for fzf: Senzu Tera
# Generated by senzu
#
# Source this file in your shell rc to apply (zsh/bash):
#
#   [ -f ~/.config/fzf/senzu-tera.sh ] && . ~/.config/fzf/senzu-tera.sh
#
# It appends the Senzu --color spec to FZF_DEFAULT_OPTS, preserving any other
# fzf options you set. To switch variants, source a different senzu fzf file
# instead (fzf merges --color flags, last one wins per element).

export FZF_DEFAULT_OPTS="${FZF_DEFAULT_OPTS:+$FZF_DEFAULT_OPTS }--color=fg:#e6eaea,bg:#152528,hl:#fda47f,fg+:#e6eaea,bg+:#293e40,hl+:#fda47f,info:#5a93aa,border:#2d4f56,prompt:#5a93aa,pointer:#a1cdd8,marker:#7aa4a1,spinner:#ad5c7c,header:#587b7b,gutter:#293e40,preview-fg:#e6eaea,preview-bg:#152528"
